//! Original JC053: historical removal at resolution, not a future listener.
use crate::{engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use std::collections::BTreeSet;
pub(crate) const ID:&str="JC053";
pub(crate) const DISCOUNT:&str="jc053-discount";
pub(crate) const DRAW:&str="jc053-draw";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct InfluenceRemoval{pub event_id:String,pub turn:u32,pub region:usize,pub region_instance:String,pub team:usize,pub amount:u32}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn definition()->Definition{let mut d=attachment_definition(target(Zone::Society,EntityKind::Any,Relation::ControlledByActor,Range::Anywhere));for mut a in [ability(DISCOUNT,"快速行动、横置：下一张鸣钟教派牌正面打出或付费翻面减1",Timing::Fast,vec![Cost::ExhaustSource],vec![],vec![Op::CostReductionOnFaceUpOrPaidReveal{filter:CardFilter::PrintedSociety("鸣钟教派".into()),amount:1}],None),ability(DRAW,"快速行动2、横置：本回合敌方势力曾被移除，可以抓一张",Timing::Fast,vec![Cost::Assets(2),Cost::ExhaustSource],vec![],vec![Op::JC053Draw],None)]{a.activation_only=true;d.abilities.push(a);}d}
fn owns(o:&Op)->bool{match o{Op::JC053Draw|Op::CostReductionOnFaceUpOrPaidReveal{filter:CardFilter::PrintedSociety(_),..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("jc053-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key.starts_with("jc053-")||f.steps.iter().any(|s|owns(&s.op))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!definition().abilities.iter().any(|v|same(v,a)){return Err("鸣钟徽记必须保留原费用、横置及独立能力程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("鸣钟徽记定义不能移植或改写".into());}Ok(())}
impl Game{
 pub(crate) fn remove_influence_recorded(&mut self,region:usize,team:usize,amount:u32){let n=amount.min(self.regions[region].influence[team]);if n==0{return;}self.record_influence_removal(region,team,n);self.regions[region].influence[team]-=n;}
 pub(crate) fn record_influence_removal(&mut self,region:usize,team:usize,amount:u32){if amount==0{return;}let r=InfluenceRemoval{event_id:self.id(),turn:self.turn,region,region_instance:self.regions[region].card.id.clone(),team,amount};self.influence_removals.push(r);}
 fn jc053_eligible(&self,actor:usize)->bool{self.influence_removals.iter().any(|r|r.turn==self.turn&&r.team!=self.team(actor))}
 pub(crate) fn validate_jc053_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){if f.source.card.definition==ID&&f.ability_key!="attach"&&!self.validated_cross_card_frame(f)?{return Err("鸣钟徽记不能伪造外来帧".into());}return Ok(());}let a=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("鸣钟徽记外来程序")?;let c=&f.source.card;if c.definition!=ID||c.face_down||f.actor>=self.players.len()||c.controller!=f.actor||c.owner>=self.players.len()||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.attachment_host_instance.as_deref()!=Some(format!("society:p{}",f.actor).as_str())||f.source.play_source.is_some()||f.source.observed_death.is_some()||f.source.death_echo.is_some()||f.source.observed_exposure.is_some()||f.source.observed_mobility_grant.is_some()||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||!f.targets.is_empty()||f.chosen_region.is_some()||!same(&f.steps,&a.ops.iter().map(|o|Step{context:f.actor,op:o.clone()}).collect::<Vec<_>>()){return Err("鸣钟徽记原秘社来源、帧或目标被改写".into());}self.mobility_immutable_identity(c)?;self.validate_batch20_payment(f,&a.costs)}
 pub(crate) fn jc053_draw_start(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_jc053_frame(&f)?;if f.cursor!=1||f.ability_key!=DRAW{return Err("鸣钟徽记须结算原抓牌能力".into());}if !self.players[f.actor].eliminated&&self.jc053_eligible(f.actor){self.choice(f.actor,"jc053-draw","鸣钟徽记：可以抓一张牌".into(),vec![ChoiceOption{id:"draw".into(),label:"抓一张牌".into(),card:None}],0,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::JC053Draw});}Ok(())}
 pub(crate) fn jc053_draw_finish(&mut self,f:&ResolutionFrame,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.validate_jc053_frame(f)?;if f.cursor!=1||f.ability_key!=DRAW||seat!=f.actor||!self.jc053_eligible(seat)||ids.len()>1||ids.first().is_some_and(|s|s!="draw")||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")}){return Err("鸣钟徽记仅接受本人原可选抓牌".into());}if !ids.is_empty(){self.draw(seat,1)?;}Ok(())}
 pub(crate) fn validate_jc053_state(&self)->RuleResult<()>{let mut ids=BTreeSet::new();for r in &self.influence_removals{if r.turn!=self.turn||r.turn==0||r.region>=self.regions.len()||r.team>1||r.amount==0||!ids.insert(&r.event_id)||!self.mystic_instance_number(&r.region_instance).zip(self.mystic_instance_number(&r.event_id)).is_some_and(|(a,b)|a<b){return Err("本回合势力移除记录身份或数量损坏".into());}}if self.modifiers.iter().any(|m|matches!(&m.filter,CardFilter::PrintedSociety(_))&&(!matches!(&m.filter,CardFilter::PrintedSociety(s)if s=="鸣钟教派")||!m.paid_reveal||m.amount!=1||m.uses>1||m.actor>=self.players.len()||m.expires_turn==0||m.expires_turn>self.turn)){return Err("鸣钟徽记减费必须精确派系、双通道和一次消费".into());}let mut frames=BTreeSet::new();for i in &self.stack{if let Some(f)=&i.frame{self.validate_jc053_frame(f)?;if frame_related(f)&&(!frames.insert(&f.frame_id)||f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.target.is_some()||i.deploy_region.is_some()||i.reveal){return Err("鸣钟徽记响应外壳损坏".into());}}}for e in &self.effects{if matches!(e,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)){return Err("鸣钟徽记没有印刷触发声明".into());}if let Effect::Frame{frame:f}=e{self.validate_jc053_frame(f)?;if frame_related(f){return Err("鸣钟徽记单步没有游离续体".into());}}}if let Some(p)=&self.pending{if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)){return Err("鸣钟徽记不能伪造触发待选".into());}if let ChoiceResolution::Frame{frame:f,choice}=&p.resolution{if frame_related(f)||matches!(choice,FrameChoice::JC053Draw){self.validate_jc053_frame(f)?;let expected=Choice{id:p.choice.id.clone(),kind:"jc053-draw".into(),title:"鸣钟徽记：可以抓一张牌".into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(f.actor),options:vec![ChoiceOption{id:"draw".into(),label:"抓一张牌".into(),card:None}],preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if f.ability_key!=DRAW||f.cursor!=1||!matches!(choice,FrameChoice::JC053Draw)||p.seat!=f.actor||!self.jc053_eligible(f.actor)||!frames.insert(&f.frame_id)||!self.mystic_instance_valid(&p.choice.id)||!same(&expected,&p.choice){return Err("鸣钟徽记待选来源、数量或独占续体损坏".into());}}}}Ok(())}
}
